{1,0,1,0,0,1,0,0,0,1}
};
for (int i = 0; i < N; ++i) {
for (int j = 0; j < N; ++j) {
draw((i, j)--(i+1, j)--(i+1, j+1)--(i, j+1)--cycle);
if (a[j][i] == 1) fill((i,j)--(i+1,j)--(i+1,j+1)--(i,j+1)--cycle,purple);
}
}
