fill((0,-1)--(2,-1)--(2,0)--(0,0)--cycle,rgb(255,240,230));
draw((0,-1)--(2,-1)--(2,0)--(0,0)--cycle,gray);
draw((0,0)--(1,0)--(1,1)--(0,1)--cycle,green);
